        const norm = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
        const want = norm(query);
        // How well the title matches decides first; the provider is only a tie-break.
        // Ranking on provider alone handed back whatever the library happened to hold,
        // however little it had to do with the query.
        const score = (t) => {
            const n = norm(t.name);
            const title = n === want ? 0 : (n && (want.includes(n) || n.includes(want))) ? 1 : 2;
            const u = String(t.uri);
            const prov = u.startsWith('library://') ? 0 : u.startsWith('spotify') ? 1 : u.startsWith('apple_music') ? 2 : 3;
            return title * 10 + prov;
        };
        const hit = tracks.slice().sort((a, b) => score(a) - score(b))[0];
        if (!hit) { msg.payload = { error: 'no match for query: ' + query }; return msg; }
        mediaUri = hit.uri;
    }

