    const track = item && item.media_item;
    msg.payload = {
        played_on: nameOf(leader),
        queue: (after && after.display_name) || queueId,
        requested_uri: mediaUri,
        state: after ? after.state : null,
        now_playing: track
            ? { title: track.name, artist: (track.artists && track.artists[0] && track.artists[0].name) || null, uri: track.uri }
            : (item ? { title: item.name } : null),
        verified: !!(after && after.state === 'playing')
